mkitem!{declare_lint ! { #[doc = " The `dropping_references` lint checks for calls to `std::mem::drop` with a reference"] #[doc = " instead of an owned value."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " # fn operation_that_requires_mutex_to_be_unlocked() {} // just to make it compile"] #[doc = " # let mutex = std::sync::Mutex::new(1); // just to make it compile"] #[doc = " let mut lock_guard = mutex.lock();"] #[doc = " std::mem::drop(&lock_guard); // Should have been drop(lock_guard), mutex"] #[doc = " // still locked"] #[doc = " operation_that_requires_mutex_to_be_unlocked();"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling `drop` on a reference will only drop the"] #[doc = " reference itself, which is a no-op. It will not call the `drop` method (from"] #[doc = " the `Drop` trait implementation) on the underlying referenced value, which"] #[doc = " is likely what was intended."] pub DROPPING_REFERENCES , Warn , "calls to `std::mem::drop` with a reference instead of an owned value" }}
mkitem!{declare_lint ! { #[doc = " The `forgetting_references` lint checks for calls to `std::mem::forget` with a reference"] #[doc = " instead of an owned value."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " let x = Box::new(1);"] #[doc = " std::mem::forget(&x); // Should have been forget(x), x will still be dropped"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling `forget` on a reference will only forget the"] #[doc = " reference itself, which is a no-op. It will not forget the underlying"] #[doc = " referenced value, which is likely what was intended."] pub FORGETTING_REFERENCES , Warn , "calls to `std::mem::forget` with a reference instead of an owned value" }}
mkitem!{declare_lint ! { #[doc = " The `dropping_copy_types` lint checks for calls to `std::mem::drop` with a value"] #[doc = " that derives the Copy trait."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " let x: i32 = 42; // i32 implements Copy"] #[doc = " std::mem::drop(x); // A copy of x is passed to the function, leaving the"] #[doc = "                    // original unaffected"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling `std::mem::drop` [does nothing for types that"] #[doc = " implement Copy](https://doc.rust-lang.org/std/mem/fn.drop.html), since the"] #[doc = " value will be copied and moved into the function on invocation."] pub DROPPING_COPY_TYPES , Warn , "calls to `std::mem::drop` with a value that implements Copy" }}
mkitem!{declare_lint ! { #[doc = " The `forgetting_copy_types` lint checks for calls to `std::mem::forget` with a value"] #[doc = " that derives the Copy trait."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust"] #[doc = " let x: i32 = 42; // i32 implements Copy"] #[doc = " std::mem::forget(x); // A copy of x is passed to the function, leaving the"] #[doc = "                      // original unaffected"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Calling `std::mem::forget` [does nothing for types that"] #[doc = " implement Copy](https://doc.rust-lang.org/std/mem/fn.drop.html) since the"] #[doc = " value will be copied and moved into the function on invocation."] #[doc = ""] #[doc = " An alternative, but also valid, explanation is that Copy types do not"] #[doc = " implement the Drop trait, which means they have no destructors. Without a"] #[doc = " destructor, there is nothing for `std::mem::forget` to ignore."] pub FORGETTING_COPY_TYPES , Warn , "calls to `std::mem::forget` with a value that implements Copy" }}
